{
  "title": "神秘古村",
  "scene": "你来到了一个被古老传说笼罩的村子，四周是高大的竹林，村里的老居民们面带神秘的微笑，偶尔有几个小孩在你身边跑过，发出银铃般的笑声。村口有一块古老的石碑，上面刻着一些难解的符号，似乎隐藏着村子的秘密。",
  "goal": "探索村庄，找到隐藏的古籍，解开村庄的秘密。",
  "choices": [
    {
      "id": "A",
      "text": "询问一位老居民关于村子的秘密。",
      "outcome": "老居民告诉你，只有找到村子中心的古老图书馆，才能找到古籍。",
      "result": "success",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "直接前往村子中心寻找图书馆。",
      "outcome": "你按照老居民的指引，发现了一条隐藏的小径，最终找到了图书馆，找到一本描述村庄历史的古籍。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "忽略老居民的话，继续在村子里闲逛。",
      "outcome": "在村子里闲逛了一阵子，你发现了一些有趣的民俗物品和故事，但始终未找到古籍。",
      "result": "partial",
      "next": "retry"
    }
  ]
}
